CAT = "cpabarLeases"; SEG = "LSE"
Q = [
("A lessor's lease transfers ownership of the equipment to the lessee at the end of the term. The lessor classifies the lease as:",
 "A sales-type lease", ["An operating lease", "A direct financing lease", "A short-term lease"],
 "Meeting any one of the five criteria in ASC 842, including transfer of ownership, makes the lease sales-type for the lessor."),
("A lease meets none of the sales-type criteria, but lease payments plus a residual value guarantee from an unrelated third party equal substantially all of the asset's fair value, and collection is probable. The lessor classifies it as:",
 "A direct financing lease", ["A sales-type lease", "An operating lease", "A failed sale and financing"],
 "ASC 842 makes such a lease direct financing. The third-party guarantee transfers the risk even though no single sales-type criterion is met."),
("At commencement of a sales-type lease, equipment has a fair value of $500,000 and a carrying amount of $380,000. The lessor's selling profit at commencement is:",
 "$120,000", ["$500,000", "$0", "$880,000"],
 "A sales-type lessor derecognizes the asset and recognizes selling profit at commencement: $500,000 - $380,000 = $120,000. A direct financing lessor would defer it.",
 500000 - 380000),
("A lessor signs a 4-year operating lease of office space with no rent in year 1 and rent of $90,000 in each of years 2 to 4. Lease income recognized in year 1 is:",
 "$67,500", ["$0", "$90,000", "$270,000"],
 "Operating lease income is recognized straight-line over the term: $270,000 / 4 = $67,500 a year, including the rent-free year.",
 3 * 90000 / 4),
("Under an operating lease, the lessor:",
 "Keeps and depreciates the asset", ["Derecognizes the asset", "Records a net investment in it", "Recognizes selling profit at once"],
 "An operating lessor continues to report the underlying asset and depreciate it, recognizing lease income over the term."),
("A sales-type lease calls for payments of $50,000 at the end of each of 5 years, with no residual value, at a rate of 6% (annuity factor 4.2124). The lessor's net investment at commencement is:",
 "$210,620", ["$250,000", "$200,000", "$235,924"],
 "The net investment is the present value of the lease payments: $50,000 x 4.2124 = $210,620. The undiscounted total is $250,000.",
 50000 * 4.2124),
("A seller-lessee sells a building and leases it back under a lease classified as a finance lease. The seller-lessee:",
 "Keeps the asset, books a liability", ["Derecognizes the building", "Recognizes the gain on sale now", "Records a right-of-use asset only"],
 "A finance leaseback means control has not passed to the buyer, so there is no sale. The seller-lessee keeps the asset and records the cash as a financial liability."),
("A sale and leaseback qualifies as a sale. The building is sold at its fair value of $2,000,000 and had a carrying amount of $1,400,000. The seller-lessee's gain is:",
 "$600,000, recognized now", ["$600,000, deferred", "$2,000,000, recognized now", "No gain, deferred"],
 "Under ASC 842, a sale at fair value recognizes the full gain, $2,000,000 - $1,400,000 = $600,000, when control of the building passes to the buyer-lessor.",
 2000000 - 1400000),
]
